-- Engine baseline 0008: storage buckets, their rules, and the realtime publication.
-- GENERATED by `pnpm --filter @engine/db cut` from a structure dump of the source database and
-- supabase-engine/allowlist.json. Do not edit by hand: change the allow-list, or add a new
-- migration after the baseline.

set search_path = public, extensions;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('event-images', 'event-images', true, 104857600, array['image/jpeg', 'image/png', 'image/gif', 'image/webp', 'video/mp4', 'video/webm', 'video/quicktime'])
on conflict (id) do nothing;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('place-images', 'place-images', true, 104857600, array['image/jpeg', 'image/png', 'image/gif', 'image/webp', 'video/mp4', 'video/webm', 'video/quicktime'])
on conflict (id) do nothing;

create policy "Event images delete own" on storage.objects
  as permissive for delete to authenticated
  using (((bucket_id = 'event-images'::text) AND (((storage.foldername(name))[1] = (auth.uid())::text) OR is_admin())));
create policy "Event images update own" on storage.objects
  as permissive for update to authenticated
  using (((bucket_id = 'event-images'::text) AND (((storage.foldername(name))[1] = (auth.uid())::text) OR is_admin())))
  with check (((bucket_id = 'event-images'::text) AND (((storage.foldername(name))[1] = (auth.uid())::text) OR is_admin())));
create policy "Event images upload own" on storage.objects
  as permissive for insert to authenticated
  with check (((bucket_id = 'event-images'::text) AND (((storage.foldername(name))[1] = (auth.uid())::text) OR is_admin())));
create policy "Place images delete own" on storage.objects
  as permissive for delete to authenticated
  using (((bucket_id = 'place-images'::text) AND (((storage.foldername(name))[1] = (auth.uid())::text) OR is_admin())));
create policy "Place images update own" on storage.objects
  as permissive for update to authenticated
  using (((bucket_id = 'place-images'::text) AND (((storage.foldername(name))[1] = (auth.uid())::text) OR is_admin())))
  with check (((bucket_id = 'place-images'::text) AND (((storage.foldername(name))[1] = (auth.uid())::text) OR is_admin())));
create policy "Place images upload" on storage.objects
  as permissive for insert to authenticated
  with check (((bucket_id = 'place-images'::text) AND (((storage.foldername(name))[1] = (auth.uid())::text) OR is_admin())));

-- realtime: the tables the app listens to
alter publication supabase_realtime add table public.notifications;
alter publication supabase_realtime add table public.messages;
alter publication supabase_realtime add table public.event_updates;
alter publication supabase_realtime add table public.broadcast_messages;
alter publication supabase_realtime add table public.volunteer_applications;
alter publication supabase_realtime add table public.suggestions;

reset search_path;

insert into engine.schema_migrations (version, name) values ('0008', 'storage_and_realtime');
